/* AINM Tempo v2.1 - planning autonome, données privées sur appareil. */
(() => {
'use strict';
const $ = id => document.getElementById(id);
const STORAGE_BASE = 'tempo_ainm_private_v1'; // compatible avec l'ancienne PWA publiée
const STORAGE_WORK = 'ainm_tempo_workspace_v2';
const STORE_DB = 'ainm-tempo-private';
const DEFAULT_WORK = () => ({version:2, created:[], patches:{}, hidden:{}, absences:[], agents:[], agentPatches:{}, chantiers:[], lastSave:null});
let base = {CH:[], AG:[], MI:[], PL:[], ACT:[]};
let work = DEFAULT_WORK();
let view = 'planning', planningMode = 'chantiers', weekStart = monday(new Date()), filters = {chantier:'',agent:'',search:'',date:'',role:''};
let page = 0, selectedAgent = null, selectedChantier = null;
const SKILLS = ['11 - Adjoint S11 / AA - Agent d’activité','C2 - TES C - RPTX/CCH avec Lorry AutoMoteur (LAM)','D2 - TES D - HMT VOIE+IS','D5 - TES D - HMT SEG N3','M1 - TES M - Annonceur/Sentinelle','M2 - TES M - ASP/Annonceur','RS - RSNCF sur le chantier / RSO','Autre mission'];
const VIEWS = {tableau:['Vue d’ensemble','Situation des chantiers et des agents'],planning:['Planning','Programmer les vacations et les équipes'],chantiers:['Chantiers','Vue consolidée des chantiers génériques'],agents:['Agents & encadrement','Profils, missions et coordonnées'],missions:['Missions de sécurité','Besoins prévus, fonctions et contrôle'],absences:['Absences & repos','Congés, repos, formations et indisponibilités'],donnees:['Données & sauvegardes','Base locale, imports et exports']};
function esc(t){return String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function iso(d){const z=new Date(d);return `${z.getFullYear()}-${String(z.getMonth()+1).padStart(2,'0')}-${String(z.getDate()).padStart(2,'0')}`;}
function at(s){const p=String(s||'').split('-').map(Number);return new Date(p[0]||2026,(p[1]||1)-1,p[2]||1);}
function addDays(d,days){const x=new Date(d);x.setDate(x.getDate()+days);return x;}
function monday(d){const x=new Date(d.getFullYear(),d.getMonth(),d.getDate());x.setDate(x.getDate()-((x.getDay()+6)%7));return x;}
function fmtDate(s,opt={day:'numeric',month:'short',year:'numeric'}){return at(s).toLocaleDateString('fr-FR',opt);}
function cleanTime(t){const s=String(t??'').trim().replace('h',':');return /^\d{1,2}:\d{2}$/.test(s)?s.padStart(5,'0'):'22:00';}
function formatTime(t){return cleanTime(t).replace(':','h');}
function dtRange(m){const from=at(m.date), to=at(m.date);const [h,min]=cleanTime(m.debut).split(':').map(Number);from.setHours(h,min,0,0);const [eh,em]=cleanTime(m.fin).split(':').map(Number);to.setHours(eh,em,0,0);if(to<=from)to.setDate(to.getDate()+1);return [from,to];}
function initials(str){return String(str).split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();}
function toast(message){const el=document.createElement('div');el.className='toast';el.textContent=message;$('toasts').appendChild(el);setTimeout(()=>el.remove(),3800);}
function readJson(key){try {return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}}
function persistWork(){work.lastSave=new Date().toISOString();try{localStorage.setItem(STORAGE_WORK,JSON.stringify(work));}catch{toast('Stockage plein : exporter une sauvegarde JSON.');} }
function openDb(){return new Promise((resolve,reject)=>{if(!indexedDB)return reject(Error('IndexedDB indisponible'));const req=indexedDB.open(STORE_DB,1);req.onupgradeneeded=()=>{req.result.createObjectStore('private');};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function idbSave(value){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction('private','readwrite');tx.objectStore('private').put(value,'base');tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error);};});}
async function idbLoad(){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction('private','readonly');const req=tx.objectStore('private').get('base');req.onsuccess=()=>{db.close();resolve(req.result||null);};req.onerror=()=>{db.close();reject(req.error);};});}
function hasData(){return base.CH.length || base.MI.length || base.AG.length;}
function validateBase(d){if(!d||!Array.isArray(d.CH)||!Array.isArray(d.AG)||!Array.isArray(d.MI)||!Array.isArray(d.PL))throw Error('JSON AINM invalide : CH / AG / MI / PL requis');return normaliseBase(d);}
async function importBase(d){const newBase=validateBase(d);await idbSave(newBase).catch(()=>{});try{localStorage.setItem(STORAGE_BASE,JSON.stringify(newBase));}catch{ /* IndexedDB prioritaire si capacité insuffisante */ }
base=newBase;filters.chantier='';filters.agent='';selectedChantier=null;selectedAgent=null;render();toast(`Import terminé : ${base.CH.length} chantiers, ${base.AG.length} profils et ${base.MI.length} affectations.`);}
function agents(){const map=new Map([...base.AG,...work.agents].map(a=>[a.id,{...a}]));for(const [id,patch] of Object.entries(work.agentPatches))if(map.has(id))map.set(id,{...map.get(id),...patch});return [...map.values()];}
function chantiers(){return [...base.CH,...work.chantiers];}
function entryKey(m){if(m.id)return m.id;return `laplace-${m.ligne}-${m.date}`;}
function allMissions(){const original=base.MI.map(x=>({...x,id:entryKey(x),origine:'LAPLACE',etat:'source'}));const created=work.created.map(x=>({...x,origine:'Tempo'}));return [...original,...created].filter(m=>!work.hidden[m.id]).map(m=>({...m,...(work.patches[m.id]||{})}));}
function byId(id){return allMissions().find(m=>m.id===id);}
function matchingAgent(m){if(m.agent_id)return agents().find(a=>a.id===m.agent_id);if(!m.agent_source)return null;const normalized=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z ]/g,' ').trim();const src=normalized(m.agent_source).split(/\s+/);const matches=agents().filter(a=>{const parts=normalized(a.nom_affiche).split(/\s+/);return src.some(t=>t.length>2 && parts.includes(t)) && src.some(t=>t.length===1 && parts.some(p=>p.startsWith(t)&&!src.includes(p)));});return matches.length===1?matches[0]:null;}
function missionAgentName(m){return m.agent_id?(agents().find(a=>a.id===m.agent_id)?.nom_affiche||m.agent_source||'Agent à préciser'):(m.agent_source||'Non affecté');}
function chantierName(id){return chantiers().find(c=>c.chantier_id===id)?.chantier||'Chantier à identifier';}
function contains(q,source){return String(source||'').toLocaleLowerCase('fr').includes(q.toLocaleLowerCase('fr'));}
function agentsOpts(value=''){return `<option value="">Tous les agents</option>`+agents().map(a=>`<option value="${esc(a.id)}" ${value===a.id?'selected':''}>${esc(a.nom_affiche)}</option>`).join('');}
function chantiersOpts(value=''){return `<option value="">Tous les chantiers</option>`+chantiers().map(c=>`<option value="${esc(c.chantier_id)}" ${value===c.chantier_id?'selected':''}>${esc(c.chantier)}</option>`).join('');}
function linkAgent(m,id){if(!id)return true;const a=matchingAgent(m);return m.agent_id===id || a?.id===id;}
function isAbsent(agent,date){return work.absences.some(x=>x.agent_id===agent && date>=x.debut && date<=x.fin);}
function conflicts(m){const a=matchingAgent(m);if(!a)return [];const [from,to]=dtRange(m);const absences=work.absences.filter(x=>x.agent_id===a.id && (x.debut<=iso(to) && x.fin>=iso(from)));const others=allMissions().filter(o=>o.id!==m.id && linkAgent(o,a.id));const overlaps=others.filter(o=>{const [x,y]=dtRange(o);return x<to && y>from;});return [...absences.map(x=>`Indisponibilité (${x.type})`),...overlaps.slice(0,5).map(x=>`Chevauchement avec ${chantierName(x.chantier_id)} le ${fmtDate(x.date)}`)];}
function highlightChip(m){return m.etat==='publie'?'<span class="chip published">Publié local</span>':m.etat==='brouillon'?'<span class="chip draft">Brouillon</span>':'<span class="chip source">Prévision LAPLACE</span>';}
function countOn(d){return allMissions().filter(m=>m.date===d).length;}
function setView(next){closeWeekSheet();if(next!==view){filters.search='';filters.date='';}view=next;page=0;selectedAgent=null;selectedChantier=null;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('sidebar').classList.remove('open');render();}
function header(title,desc,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="head-actions">${actions}</div></div>`;}
function metrics(items){return `<div class="metric-grid">${items.map(([n,l,f,s])=>`<article class="metric-card"><div class="label">${esc(l)}</div><div class="value">${esc(n)}</div><div class="foot">${esc(f)}</div><div class="symbol">${s}</div></article>`).join('')}</div>`;}
function upcoming(){const now=iso(new Date());return allMissions().filter(m=>m.date>=now).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,6);}
function missionRow(m){return `<div class="row-card clickable tempo-colored-row" ${siteTheme(m.chantier_id)} data-open-mission="${esc(m.id)}" tabindex="0" role="button"><div style="min-width:0"><div class="main-label">${esc(chantierName(m.chantier_id))}</div><div class="row-meta">${esc(fmtDate(m.date))} · ${formatTime(m.debut)}–${formatTime(m.fin)} · ${esc(missionAgentName(m))}</div><div class="stack">${highlightChip(m)} <span class="chip role">${esc(String(m.mission_securite_demandee||'Mission à préciser').slice(0,55))}</span></div></div><span class="text-muted">›</span></div>`;}
function dashboard(){const now=iso(new Date()), today=allMissions().filter(m=>m.date===now), draft=allMissions().filter(m=>m.etat==='brouillon');const next=upcoming();return header('Bonjour, bienvenue sur Tempo','Ton planning AINM, du chantier jusqu’à chaque agent.',`<button class="btn btn-secondary" data-action="go-planning">▦ Voir la semaine</button>`)+metrics([[chantiers().length,'Chantiers génériques','Étalonnage inclus','▤'],[agents().length,'Agents & encadrement',`${agents().filter(a=>a.categorie==='encadrement').length} encadrants`,'♙'],[today.length,'Missions aujourd’hui','Prévisions et brouillons','◷'],[draft.length,'À préparer','Brouillons sur cet appareil','◇']])+`<div class="split"><div class="panel"><div class="panel-head"><div><h2>Prochaines vacations</h2><p>Affectations issues de LAPLACE et missions ajoutées</p></div><button class="btn small" data-action="go-planning">Planning ›</button></div>${next.length?next.map(missionRow).join(''):empty('Aucune vacation à venir','Utiliser le planning pour créer une vacation.')}</div><div class="panel"><div class="panel-head"><div><h2>Préparation rapide</h2><p>Les outils de ton planning</p></div></div><div class="stats-list"><div><span>Créer une vacation</span><button class="btn small" data-action="create">＋ Ajouter</button></div><div><span>Déclarer une absence</span><button class="btn small" data-action="absence">＋ Absence</button></div><div><span>Consulter les équipes</span><button class="btn small" data-action="agents">Profils</button></div><div><span>Sauvegarder ton travail</span><button class="btn small" data-action="export">Exporter JSON</button></div></div><div class="note-panel">${hasData()?`Base locale chargée : <b>${base.MI.length} affectations LAPLACE</b> et <b>${base.PL.length} notes de planning</b>. Les affectations importées ne sont pas des confirmations d’habilitation.`:'Charge les données privées AINM dans « Données & sauvegardes » pour afficher les vrais agents et chantiers.'}</div></div></div>`;}
function weekLabel(){return `${fmtDate(iso(weekStart),{day:'numeric',month:'short'})} – ${fmtDate(iso(addDays(weekStart,6)),{day:'numeric',month:'short',year:'numeric'})}`;}
const TempoCore = window.TempoPlanningCore;
let weekVisualFilter='all';
let weekDayFocus='';
let lastSheetTrigger=null;
const WEEKDAY_SHORT=['dim.','lun.','mar.','mer.','jeu.','ven.','sam.'];
function siteTheme(id){const t=TempoCore.theme(id);return `style="--site-accent:${t.accent};--site-soft:${t.soft}"`;}
function isThisWeek(m){const days=TempoCore.weekDays(weekStart);return days.includes(m.date);}
function countPeople(items){return new Set(items.map(TempoCore.agentKey)).size;}
function siteCard(g){
  const s=g.sessions;
  const first=s[0];
  const time=s.length===1?`${formatTime(first.debut)} – ${formatTime(first.fin)}`:`${s.length} séances · ${formatTime(first.debut)}…`;
  const nightOnly=g.nightCount===g.items.length;
  const hasNight=g.nightCount>0;
  const daytype=nightOnly?'Nuit':hasNight?'Jour / nuit':'Jour';
  const published=g.items.filter(x=>x.etat==='publie').length;
  const drafts=g.items.filter(x=>x.etat==='brouillon').length;
  const status=drafts?`${drafts} brouillon${drafts>1?'s':''}`:published===g.items.length?'Publié local':'Prévision';
  const id=esc(g.chantier_id),d=esc(g.date);
  return `<button type="button" class="tempo-site-bubble" ${siteTheme(g.chantier_id)} data-week-site="${id}" data-week-date="${d}" aria-label="${esc(chantierName(g.chantier_id))}, ${esc(fmtDate(g.date))}, ${g.agentsCount} agent(s), ouvrir les équipes et séances">
    <span class="tempo-site-top"><span class="tempo-site-dot" aria-hidden="true"></span><span class="tempo-site-name">${esc(chantierName(g.chantier_id))}</span><span class="tempo-card-chevron" aria-hidden="true">›</span></span>
    <span class="tempo-site-schedule"><span class="tempo-daytype ${nightOnly?'tempo-is-night':''}">${nightOnly?'☾':hasNight?'◐':'☀'} ${daytype}</span><span class="tempo-time">${esc(time)}</span></span>
    <span class="tempo-site-bottom"><span><b>${g.agentsCount}</b> agent${g.agentsCount>1?'s':''}</span><span class="tempo-role-count">${g.missionsCount} fonction${g.missionsCount>1?'s':''}</span></span>
    <span class="tempo-source-status">${esc(status)}${s.length>1?` · ${s.length} séances`:''}</span>
   </button>`;
}
function headerWeekNav(){return `<div class="tempo-week-nav"><button type="button" class="tempo-week-arrow" data-week="-7" aria-label="Semaine précédente">‹</button><div class="tempo-week-range"><span class="tempo-week-eyebrow">PLANNING HEBDOMADAIRE</span><strong>${esc(weekLabel())}</strong></div><button type="button" class="tempo-week-arrow" data-week="7" aria-label="Semaine suivante">›</button><button type="button" class="tempo-today" data-week="0">Cette semaine</button></div>`;}
function weekMiniStats(weekly){const uniqueSites=new Set(weekly.map(m=>m.chantier_id)).size;const people=countPeople(weekly);const slots=TempoCore.groupBySiteAndDay(weekly).reduce((n,g)=>n+g.sessions.length,0);const abs=work.absences.filter(a=>a.debut<=iso(addDays(weekStart,6))&&a.fin>=iso(weekStart)).length;
  return `<div class="tempo-mini-stats"><div><strong>${uniqueSites}</strong><span>chantier${uniqueSites>1?'s':''} actif${uniqueSites>1?'s':''}</span></div><div><strong>${people}</strong><span>agent${people>1?'s':''} prévu${people>1?'s':''}</span></div><div><strong>${slots}</strong><span>séance${slots>1?'s':''}</span></div><div><strong>${abs}</strong><span>absence${abs>1?'s':''} déclarée${abs>1?'s':''}</span></div></div>`;}
function planning(){
  const week=TempoCore.weekDays(weekStart);
  const selected=allMissions().filter(m=>week.includes(m.date)&&(!filters.chantier||m.chantier_id===filters.chantier)&&(!filters.agent||linkAgent(m,filters.agent))&&(!filters.search||contains(filters.search,`${missionAgentName(m)} ${chantierName(m.chantier_id)} ${m.mission_securite_demandee}`)));
  const modes=`<div class="tempo-mode-switch" role="group" aria-label="Mode de planning"><button data-mode="chantiers" class="${planningMode==='chantiers'?'sel':''}" aria-pressed="${planningMode==='chantiers'}">Par chantier</button><button data-mode="agents" class="${planningMode==='agents'?'sel':''}" aria-pressed="${planningMode==='agents'}">Par agent</button></div>`;
  const sum=weekMiniStats(selected);
  const search=`<details class="tempo-advanced-filters" ${filters.chantier||filters.agent||filters.search?'open':''}><summary>Recherche et filtres avancés ${filters.chantier||filters.agent||filters.search?'(actifs)':''}</summary><div class="tempo-search-row"><label>Chantier <select id="filterChantier">${chantiersOpts(filters.chantier)}</select></label><label>Agent <select id="filterAgent">${agentsOpts(filters.agent)}</select></label><label class="tempo-search-input">Rechercher <input id="filterSearch" type="search" autocomplete="off" placeholder="Nom, mission de sécurité…" value="${esc(filters.search)}"></label></div></details>`;
  const filterOptions=[['all','Toutes les séances'],['day','Jour'],['night','Nuit'],['security','Sécurité']];
  const countMode=x=>TempoCore.groupBySiteAndDay(TempoCore.filterWeek(selected,week,x)).reduce((n,g)=>n+g.sessions.length,0);
  const pills=`<div class="tempo-pills" role="group" aria-label="Filtrer les vacations">${filterOptions.map(([key,label])=>`<button data-week-filter="${key}" aria-pressed="${weekVisualFilter===key}" class="tempo-pill ${weekVisualFilter===key?'active':''}">${esc(label)} <span>${countMode(key)}</span></button>`).join('')}</div>`;
  const filtered=TempoCore.filterWeek(selected,week,weekVisualFilter);
  const weekdayButtons=`<div class="tempo-daystrip" role="group" aria-label="Jours de la semaine"><button data-week-dayfocus="" class="${weekDayFocus===''?'active':''}" aria-pressed="${weekDayFocus===''}">7 jours</button>${week.map((d,i)=>`<button data-week-dayfocus="${d}" class="${weekDayFocus===d?'active':''}" aria-pressed="${weekDayFocus===d}"><small>${esc(WEEKDAY_SHORT[at(d).getDay()])}</small><b>${at(d).getDate()}</b></button>`).join('')}</div>`;
  const groups=TempoCore.groupBySiteAndDay(filtered);
  let board='';
  if(planningMode==='chantiers'){
    for(const d of week){if(weekDayFocus&&weekDayFocus!==d)continue;const today=iso(new Date())===d;const dayGroups=groups.filter(g=>g.date===d).sort((a,b)=>chantierName(a.chantier_id).localeCompare(chantierName(b.chantier_id),'fr'));const w=at(d).toLocaleDateString('fr-FR',{weekday:'long'});
      board+=`<section class="tempo-day-block ${today?'tempo-day-today':''}" aria-label="${esc(w+' '+fmtDate(d))}"><div class="tempo-day-heading"><div class="tempo-date"><b>${esc(w.charAt(0).toUpperCase()+w.slice(1))} ${at(d).getDate()}</b><span>${at(d).toLocaleDateString('fr-FR',{month:'short'})}${today?' · aujourd’hui':''}</span></div><div class="tempo-day-count">${dayGroups.length} chantier${dayGroups.length>1?'s':''} · ${dayGroups.reduce((n,g)=>n+g.sessions.length,0)} séance${dayGroups.reduce((n,g)=>n+g.sessions.length,0)>1?'s':''}</div></div><div class="tempo-day-bubbles">${dayGroups.length?dayGroups.map(siteCard).join(''):'<p class="tempo-empty-day">Aucune séance prévue</p>'}</div></section>`;
    }
  } else {
    for(const d of week){if(weekDayFocus&&weekDayFocus!==d)continue;const dayM=filtered.filter(m=>m.date===d).sort((a,b)=>missionAgentName(a).localeCompare(missionAgentName(b),'fr'));const w=at(d).toLocaleDateString('fr-FR',{weekday:'long'});
      board+=`<section class="tempo-day-block"><div class="tempo-day-heading"><div class="tempo-date"><b>${esc(w.charAt(0).toUpperCase()+w.slice(1))} ${at(d).getDate()}</b><span>${at(d).toLocaleDateString('fr-FR',{month:'short'})}</span></div><span class="tempo-day-count">${countPeople(dayM)} agent${countPeople(dayM)>1?'s':''} prévu${countPeople(dayM)>1?'s':''}</span></div><div class="tempo-agent-rows">${dayM.length?dayM.map(m=>`<button class="tempo-agent-mission" ${siteTheme(m.chantier_id)} data-open-mission="${esc(m.id)}"><span class="tempo-agent-line"><b>${esc(missionAgentName(m))}</b><small>${esc(chantierName(m.chantier_id))}</small></span><span>${formatTime(m.debut)} – ${formatTime(m.fin)}</span><span class="tempo-agent-role">${esc(String(m.mission_securite_demandee||'Fonction à préciser').slice(0,72))}</span></button>`).join(''):'<p class="tempo-empty-day">Aucune affectation prévue</p>'}</div></section>`;
    }
  }
  const legend=`<details class="tempo-legend"><summary>Repères couleurs · ${chantiers().length} chantiers</summary><div>${chantiers().map(c=>`<span ${siteTheme(c.chantier_id)}><i></i>${esc(c.chantier.replace(/^Chantier\s+/i,''))}</span>`).join('')}</div></details>`;
  return `<div class="tempo-planning-page">${header('Planning AINM','La semaine entière en un coup d’œil : touchez un chantier pour connaître son équipe.',`<button class="btn btn-secondary" data-action="export-csv">CSV</button><button class="btn btn-primary" data-action="create">＋ Affectation</button>`)}<section class="tempo-week-card">${headerWeekNav()}${!hasData()?`<div class="tempo-import-hint">Aucune base AINM chargée sur cet appareil.<button class="btn btn-primary small" data-action="import">Importer ma base JSON</button></div>`:''}${sum}${modes}${pills}${weekdayButtons}${search}<div class="tempo-overview-head"><strong>${planningMode==='chantiers'?'Vue globale des chantiers':'Affectations par agent'}</strong><span>${planningMode==='chantiers'?'Toucher un bloc pour afficher les séances et les agents':'Toucher une affectation pour voir les détails'}</span></div><div class="tempo-week-list">${board}</div>${planningMode==='chantiers'?legend:''}<div class="tempo-import-clarification">Les fonctions affichées proviennent de besoins prévus. Elles ne constituent pas une vérification des habilitations. Les modifications restent sur cet appareil.</div></section></div>`;
}
function chantierView(){
  const items=chantiers();const week=TempoCore.weekDays(weekStart),missions=allMissions();const weekly=missions.filter(m=>week.includes(m.date));const group=TempoCore.groupBySiteAndDay(weekly);
  return header('Les chantiers AINM','Couleur fixe pour chaque chantier générique, toutes les phases WE/WER regroupées.',`<button class="btn btn-primary" data-action="create-chantier">＋ Chantier</button>`)+`<div class="toolbar"><div class="field" style="max-width:480px"><label>Rechercher un chantier</label><input id="filterSearch" value="${esc(filters.search)}" placeholder="Montereau, Thomery, Étalonnage…"></div></div><section class="tempo-chantier-list">${items.filter(c=>contains(filters.search,c.chantier)).map(c=>{const matches=group.filter(g=>g.chantier_id===c.chantier_id),n=missions.filter(m=>m.chantier_id===c.chantier_id).length,agentsThisWeek=new Set(matches.flatMap(g=>g.items).map(TempoCore.agentKey)).size;return `<button ${siteTheme(c.chantier_id)} data-chantier="${esc(c.chantier_id)}" class="tempo-chantier-tile"><i class="tempo-color-marker"></i><span class="tempo-chantier-name"><b>${esc(c.chantier)}</b><small>${matches.length} jour${matches.length>1?'s':''} prévu${matches.length>1?'s':''} cette semaine</small></span><span class="tempo-chantier-figures"><b>${agentsThisWeek}</b><small>agents semaine</small></span><span class="tempo-chantier-figures"><b>${n}</b><small>affectations base</small></span><span aria-hidden="true">›</span></button>`;}).join('')||empty('Aucun chantier','Modifier la recherche.')}</section>`;
}
function chantierDetail(id){
  const c=chantiers().find(x=>x.chantier_id===id);if(!c){selectedChantier=null;return chantierView();}
  const all=allMissions().filter(m=>m.chantier_id===id);const week=TempoCore.weekDays(weekStart),weekly=all.filter(m=>week.includes(m.date));const groups=TempoCore.groupBySiteAndDay(weekly);const dates=week.map(d=>({date:d,items:groups.filter(g=>g.date===d)}));
  const nAgents=countPeople(weekly),nSessions=groups.reduce((s,g)=>s+g.sessions.length,0);
  return `<div class="breadcrumb"><button class="btn small" data-action="back-chantier">‹ Tous les chantiers</button></div><section class="tempo-site-detail" ${siteTheme(id)}><div class="tempo-detail-head"><i class="tempo-color-marker"></i><div><span class="tempo-detail-eyebrow">CHANTIER GÉNÉRIQUE</span><h1>${esc(c.chantier)}</h1><p>${esc(c.compte||'AINM')} · ${all.length} affectations source et locales</p></div><button class="btn btn-primary" data-action="create" data-target-chantier="${esc(id)}">＋ Affectation</button></div><div class="tempo-detail-statrow"><span><b>${nSessions}</b> séances semaine</span><span><b>${nAgents}</b> agents prévus</span><span><b>${groups.length}</b> jours programmés</span></div></section><section class="tempo-week-card tempo-detail-calendar">${headerWeekNav()}<div class="tempo-overview-head"><strong>Séances et équipes de la semaine</strong><span>Ouvrir une journée pour voir les personnes affectées</span></div><div class="tempo-week-list">${dates.map(({date,items})=>`<section class="tempo-day-block"><div class="tempo-day-heading"><div class="tempo-date"><b>${esc(at(date).toLocaleDateString('fr-FR',{weekday:'long',day:'numeric'}))}</b></div><div class="tempo-day-count">${items.reduce((n,g)=>n+g.sessions.length,0)} séance(s)</div></div><div class="tempo-day-bubbles">${items.length?items.map(siteCard).join(''):'<p class="tempo-empty-day">Aucune séance prévue</p>'}</div></section>`).join('')}</div><div class="tempo-import-clarification">Le nom du chantier est générique. Les variantes WE/WER et les informations de sécurité restent dans les données de chaque affectation.</div></section>`;
}
function closeWeekSheet(){const el=$('weekSheet');if(!el||el.hidden)return;el.hidden=true;$('weekSheetBody').innerHTML='';document.body.classList.remove('tempo-sheet-open');if(lastSheetTrigger?.isConnected)lastSheetTrigger.focus();lastSheetTrigger=null;}
function openWeekSheet(date,id,trigger){
  const entries=allMissions().filter(m=>m.date===date&&m.chantier_id===id);
  if(!entries.length){toast('Aucune affectation pour cette journée.');return;}
  const groups=TempoCore.groupSessions(entries),total=countPeople(entries);lastSheetTrigger=trigger||document.activeElement;
  const whoList=session=>{
    const perAgent=new Map();
    for(const m of session.items){const k=TempoCore.agentKey(m);if(!perAgent.has(k))perAgent.set(k,{name:missionAgentName(m),items:[]});perAgent.get(k).items.push(m);}
    return [...perAgent.values()].sort((a,b)=>a.name.localeCompare(b.name,'fr')).map(a=>{
      const m=a.items[0],agent=matchingAgent(m);const tel=String(agent?.telephone||m.telephone_source||'').replace(/[^\d+]/g,'');const safeTel=/^\+?\d{8,15}$/.test(tel)?tel:'';
      const roles=[...new Set(a.items.map(x=>x.mission_securite_demandee).filter(Boolean))];
      const doubtful=a.items.some(x=>x.identite_confirmee===false);
      return `<div class="tempo-team-row"><span class="tempo-avatar">${esc(initials(a.name))}</span><div class="tempo-team-data"><strong>${esc(a.name)}</strong><div class="tempo-team-roles">${roles.length?roles.map(r=>`<span>${esc(r)}</span>`).join(''):'<span>Fonction à renseigner</span>'}</div>${doubtful?'<small>Identité à confirmer dans LAPLACE</small>':''}</div>${safeTel?`<a class="tempo-phone" href="tel:${safeTel}" aria-label="Appeler ${esc(a.name)} — numéro source à vérifier" title="Numéro à vérifier">☎</a>`:''}<button class="tempo-team-open" type="button" data-open-mission="${esc(m.id)}" aria-label="Consulter la mission de ${esc(a.name)}">›</button></div>`;
    }).join('');
  };
  const html=`<div class="tempo-sheet-head" ${siteTheme(id)}><div class="tempo-sheet-title"><span class="tempo-site-dot" aria-hidden="true"></span><div><small id="weekSheetTitle">${esc(chantierName(id))}</small><h2>${esc(fmtDate(date,{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</h2></div></div><button type="button" class="tempo-sheet-close" data-sheet-close aria-label="Fermer le détail">✕</button></div><div class="tempo-sheet-summary"><span><b>${groups.length}</b> séance${groups.length>1?'s':''}</span><span><b>${total}</b> agent${total>1?'s':''} prévu${total>1?'s':''}</span><span><b>${entries.length}</b> affectation${entries.length>1?'s':''}</span></div><div class="tempo-sheet-scroll">${groups.map((g,i)=>`<section class="tempo-session"><div class="tempo-session-heading"><div><span class="tempo-session-index">SÉANCE ${i+1}</span><h3>${g.night?'☾ Nuit':'☀ Jour'} · ${formatTime(g.debut)} – ${formatTime(g.fin)}${TempoCore.minutes(g.fin)<=TempoCore.minutes(g.debut)?' (+1 jour)':''}</h3></div><b>${g.agentCount} agent${g.agentCount>1?'s':''}</b></div><div class="tempo-session-teams">${whoList(g)}</div></section>`).join('')}</div><div class="tempo-sheet-foot"><div class="tempo-sheet-hint">Missions prévues : compétences et habilitations à vérifier.</div><div class="tempo-sheet-actions"><button class="btn btn-secondary" data-sheet-chantier="${esc(id)}">Voir le chantier</button><button class="btn btn-primary" data-sheet-add="${esc(id)}" data-week-date="${esc(date)}">＋ Affectation</button></div></div>`;
  $('weekSheetBody').innerHTML=html;
  $('weekSheet').hidden=false;
  document.body.classList.add('tempo-sheet-open');
  $('weekSheet').querySelector('.tempo-sheet-close').focus();
}

function agentView(){const list=agents().filter(a=>contains(filters.search,`${a.nom_affiche} ${a.categorie}`));return header('Agents & encadrement',`${agents().length} profils dont ${agents().filter(a=>a.categorie==='encadrement').length} encadrants`, `<button class="btn btn-primary" data-action="new-agent">＋ Agent</button>`)+`<div class="toolbar"><div class="field" style="max-width:470px"><label>Rechercher dans l’annuaire</label><input id="filterSearch" value="${esc(filters.search)}" placeholder="Nom ou fonction…"></div></div><section class="panel">${list.map(a=>{const count=allMissions().filter(m=>linkAgent(m,a.id)).length;return `<div class="row-card clickable" data-agent="${esc(a.id)}"><div class="row-title"><div class="avatar">${esc(initials(a.nom_affiche))}</div><div><div class="main-label">${esc(a.nom_affiche)}</div><div class="row-meta">${a.categorie==='encadrement'?'Encadrement':'Agent'} · ${count} mission(s) rapprochée(s)</div></div></div><span class="text-muted">›</span></div>`;}).join('')||empty('Aucun profil trouvé','Utilisez une autre recherche.')}</section>`;}
function agentDetail(id){const a=agents().find(x=>x.id===id);if(!a){selectedAgent=null;return agentView();}const missions=allMissions().filter(x=>linkAgent(x,id)).sort((x,y)=>y.date.localeCompare(x.date));const notes=base.PL.filter(x=>x.agent_id===id).sort((x,y)=>y.date.localeCompare(x.date));const abs=work.absences.filter(x=>x.agent_id===id);return `<div class="breadcrumb"><button class="btn small" data-action="back-agent">‹ Tous les agents</button></div>`+header(a.nom_affiche,a.categorie==='encadrement'?'Profil encadrement':'Profil agent',`<button class="btn btn-secondary" data-edit-agent="${esc(id)}">Modifier le profil</button><button class="btn btn-primary" data-action="create" data-target-agent="${esc(id)}">＋ Vacation</button>`)+`<div class="split"><section class="panel"><div class="panel-head"><h2>Affectations & missions</h2><span class="badge-count">${missions.length} rapprochée(s)</span></div>${missions.length?missions.slice(0,80).map(missionRow).join(''):empty('Pas de mission rapprochée','Les libellés LAPLACE abrégés nécessitent parfois un rapprochement manuel.')}${missions.length>80?`<p class="small-note">80 missions affichées sur ${missions.length}.</p>`:''}</section><section class="panel"><h2>Identité et disponibilité</h2><div class="stats-list" style="margin-top:15px"><div><span>Téléphone</span><b>${esc(a.telephone||'À compléter')}</b></div><div><span>E-mail</span><b>${esc(a.email||'À compléter')}</b></div><div><span>Qualifications</span><b>Non vérifiées par Tempo</b></div></div><div class="note-panel">Les affectations importées avec nom abrégé peuvent être rapprochées automatiquement par correspondance apparente. Vérifier l’identité avant tout usage opérationnel.</div><h3>Absences déclarées</h3>${abs.map(x=>`<p class="small-note">${fmtDate(x.debut)} → ${fmtDate(x.fin)} · ${esc(x.type)}</p>`).join('')||'<p class="small-note">Aucune dans le planning local</p>'}<h3 style="margin-top:18px">Annotations du planning AINM (${notes.length})</h3>${notes.slice(0,30).map(n=>`<p class="small-note">${fmtDate(n.date)} : ${esc(n.annotation)}</p>`).join('')||'<p class="small-note">Aucune annotation source</p>'}</section></div>`;}
function missionsView(){const list=allMissions().filter(m=>(!filters.chantier||m.chantier_id===filters.chantier)&&(!filters.agent||linkAgent(m,filters.agent))&&(!filters.date||m.date===filters.date)&&(!filters.search||contains(filters.search,`${m.mission_securite_demandee} ${m.agent_source} ${chantierName(m.chantier_id)}`))).sort((a,b)=>b.date.localeCompare(a.date));const start=page*80;return header('Missions de sécurité',`${list.length} affectation(s) selon les filtres`,`<button class="btn btn-primary" data-action="create">＋ Mission</button>`)+`<section class="panel"><div class="filters-bar"><div class="field"><label>Chantier</label><select id="filterChantier">${chantiersOpts(filters.chantier)}</select></div><div class="field"><label>Agent</label><select id="filterAgent">${agentsOpts(filters.agent)}</select></div><div class="field"><label>Date</label><input id="filterDate" type="date" value="${esc(filters.date)}"></div><div class="field"><label>Recherche</label><input id="filterSearch" value="${esc(filters.search)}" placeholder="S11, TES D, agent…"></div></div><div class="table-wrapper"><table class="list-table"><thead><tr><th>Date / horaire</th><th>Chantier</th><th>Agent</th><th>Fonction demandée</th><th>Origine</th></tr></thead><tbody>${list.slice(start,start+80).map(m=>`<tr class="clickable" data-open-mission="${esc(m.id)}"><td>${esc(fmtDate(m.date))}<div class="row-meta">${formatTime(m.debut)}–${formatTime(m.fin)}</div></td><td>${esc(chantierName(m.chantier_id))}</td><td>${esc(missionAgentName(m))}</td><td>${esc(m.mission_securite_demandee||'—')}</td><td>${highlightChip(m)}</td></tr>`).join('')}</tbody></table></div>${!list.length?empty('Aucune mission','Modifier les filtres ou ajouter une vacation.'):''}<div class="form-actions"><span class="text-muted smalltext">${list.length?`${start+1}–${Math.min(start+80,list.length)} sur ${list.length}`:'0 résultats'}</span><button class="btn small" data-page="-1" ${page===0?'disabled':''}>Précédent</button><button class="btn small" data-page="1" ${start+80>=list.length?'disabled':''}>Suivant</button></div></section>`;}
function absenceView(){return header('Absences & repos','Éviter les doubles mobilisations avant de publier une vacation.',`<button class="btn btn-primary" data-action="absence">＋ Déclarer</button>`)+`<section class="panel"><div class="panel-head"><h2>Indisponibilités enregistrées</h2><span class="text-muted smalltext">Enregistrées uniquement sur ce téléphone</span></div>${work.absences.length?work.absences.sort((x,y)=>x.debut.localeCompare(y.debut)).map(a=>`<div class="row-card"><div><div class="main-label">${esc(agents().find(x=>x.id===a.agent_id)?.nom_affiche||'Agent non reconnu')}</div><div class="row-meta">${fmtDate(a.debut)} → ${fmtDate(a.fin)} · ${esc(a.type)} ${a.note?'· '+esc(a.note):''}</div></div><button class="btn small btn-danger" data-remove-absence="${esc(a.id)}">Retirer</button></div>`).join(''):empty('Aucune indisponibilité enregistrée','Ajoute les absences et jours de repos de tes équipes.')}</section>`;}
function empty(a,b){return `<div class="empty"><strong>${esc(a)}</strong>${esc(b)}</div>`;}
function donneesView(){return header('Données & sauvegardes','Import des plannings Excel préparés, gestion locale et exports')+`<div class="two-col"><section class="panel"><h2>Base privée AINM</h2><p class="small-note">La base LAPLACE et le planning du personnel restent hors du dépôt GitHub.</p>${metricsMini()}<div class="form-actions" style="justify-content:start"><button class="btn btn-primary" data-action="import">Importer la base JSON</button><button class="btn" data-action="export">Sauvegarde complète</button></div><p class="small-note">Compatible avec l’ancien fichier local AINM Tempo, y compris les variantes WE/WER/SQ normalisées.</p></section><section class="panel"><h2>Réversibilité et sécurité</h2><div class="note-panel">Les publications et modifications sont enregistrées <b>localement</b>. Aucun agent ne les verra sur son propre téléphone tant qu’un serveur avec authentification n’est pas connecté.</div><div class="stats-list"><div><span>Vacations créées</span><b>${work.created.length}</b></div><div><span>Vacations corrigées</span><b>${Object.keys(work.patches).length}</b></div><div><span>Absences</span><b>${work.absences.length}</b></div></div><div class="form-actions" style="justify-content:start"><button class="btn" data-action="export-csv">CSV</button><button class="btn" data-action="export-ics">Calendrier ICS</button><button class="btn btn-danger" data-action="clear-work">Effacer le travail local</button></div></section></div>`;}
function metricsMini(){return `<div class="stats-list" style="margin-top:16px"><div><span>Chantiers</span><b>${base.CH.length}</b></div><div><span>Agents & encadrement</span><b>${base.AG.length}</b></div><div><span>Affectations LAPLACE</span><b>${base.MI.length}</b></div><div><span>Annotations de planning</span><b>${base.PL.length}</b></div></div>`;}
function render(){closeWeekSheet();const [title,subtitle]=VIEWS[view];$('pageTitle').textContent=title;$('pageSubtitle').textContent=subtitle;let h='';if(view==='tableau')h=dashboard();if(view==='planning')h=planning();if(view==='chantiers')h=selectedChantier?chantierDetail(selectedChantier):chantierView();if(view==='agents')h=selectedAgent?agentDetail(selectedAgent):agentView();if(view==='missions')h=missionsView();if(view==='absences')h=absenceView();if(view==='donnees')h=donneesView();$('viewRoot').innerHTML=h;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function showModal(title,body){$('modalTitle').textContent=title;$('modalContent').innerHTML=`<div class="modal-content">${body}</div>`;$('modal').hidden=false;document.body.style.overflow='hidden';}
function closeModal(){$('modal').hidden=true;document.body.style.overflow='';}
function getVal(form,name){return form.elements.namedItem(name)?.value?.trim()||'';}
function randomId(){return 'tempo-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);}
function modalMission(m=null,defaults={}){const agent=m?.agent_id||defaults.agent||'', chantier=m?.chantier_id||defaults.chantier||'',date=m?.date||defaults.date||iso(new Date());const options=chantiersOpts(chantier).replace('Tous les chantiers','Choisir le chantier');const agentsOptions=agentsOpts(agent).replace('Tous les agents','Choisir un agent');const source=m?.origine==='LAPLACE';const body=`<div class="note-panel">${source?'Correction locale d’une prévision LAPLACE ; la ligne source sera conservée.':'Mission en préparation. La publication locale ne prévient pas les agents.'}</div><form id="missionForm"><input type="hidden" name="id" value="${esc(m?.id||'')}"><div class="form-grid"><div class="field span-all"><label>Chantier *</label><select required name="chantier_id">${options}</select></div><div class="field"><label>Jour de la prise de service *</label><input required name="date" type="date" value="${esc(date)}"></div><div class="field"><label>Agent *</label><select name="agent_id" required>${agentsOptions}</select></div><div class="field"><label>Début *</label><input name="debut" type="time" required value="${cleanTime(m?.debut||'22:00')}"></div><div class="field"><label>Fin *</label><input name="fin" type="time" required value="${cleanTime(m?.fin||'06:00')}"></div><div class="field span-all"><label>Mission / fonction de sécurité demandée *</label><input list="missionsListe" name="mission_securite_demandee" required value="${esc(m?.mission_securite_demandee||'')}" placeholder="Ex. Adjoint S11, TES D, ASP…"><datalist id="missionsListe">${SKILLS.map(s=>`<option value="${esc(s)}">`).join('')}</datalist></div><div class="field span-all"><label>Rendez-vous / lieu de prise de service</label><input name="rendez_vous" value="${esc(m?.rendez_vous||'')}" placeholder="Ex. Base vie du chantier"></div><div class="field span-all"><label>Matériel, notes et consignes</label><textarea name="commentaire" placeholder="Consignes, matériel à prévoir…">${esc(m?.commentaire||'')}</textarea></div></div><p class="small-note">Pour une nuit 22h00 → 06h00, la fin est calculée au lendemain. Les missions prévues ne prouvent pas les habilitations.</p><div class="form-actions">${m?`<button type="button" class="btn btn-danger" data-remove-mission="${esc(m.id)}">Retirer</button>`:''}<button type="button" class="btn" data-close>Annuler</button><button type="submit" name="choice" value="brouillon" class="btn btn-secondary">Enregistrer brouillon</button><button type="submit" name="choice" value="publie" class="btn btn-primary">Publier sur cet appareil</button></div></form>`;showModal(m?'Modifier la vacation':'Nouvelle vacation',body);}
function modalDetail(id){const m=byId(id);if(!m)return toast('Mission introuvable');const problems=conflicts(m);showModal('Détail de la vacation',`<div class="row-meta">${fmtDate(m.date)} • ${formatTime(m.debut)} – ${formatTime(m.fin)}</div><h2 style="margin:12px 0 7px">${esc(chantierName(m.chantier_id))}</h2><p><b>${esc(missionAgentName(m))}</b></p><div class="stack">${highlightChip(m)}${dtRange(m)[1].getDate()!==at(m.date).getDate()?'<span class="chip night">Fin le lendemain</span>':''}</div><h3 style="margin-top:20px">Mission de sécurité demandée</h3><p>${esc(m.mission_securite_demandee||'Non renseignée')}</p>${m.rendez_vous?`<h3 style="margin-top:14px">Rendez-vous</h3><p>${esc(m.rendez_vous)}</p>`:''}${m.commentaire?`<h3 style="margin-top:14px">Consignes</h3><p>${esc(m.commentaire)}</p>`:''}${problems.length?`<div class="danger-panel" style="margin-top:17px"><b>Points à vérifier :</b><ul>${problems.map(p=>`<li>${esc(p)}</li>`).join('')}</ul></div>`:''}<p class="small-note">${m.origine==='LAPLACE'?`Source : LAPLACE, ligne ${esc(m.ligne)}. Habilitation non vérifiée.`:'Créée localement dans AINM Tempo.'}</p><div class="form-actions"><button class="btn" data-close>Fermer</button><button class="btn btn-primary" data-edit-mission="${esc(id)}">Modifier</button></div>`);}
function saveMission(form,mode){const id=getVal(form,'id');const existing=id?byId(id):null;const agent_id=getVal(form,'agent_id');const a=agents().find(x=>x.id===agent_id);const fields={chantier_id:getVal(form,'chantier_id'),date:getVal(form,'date'),agent_id,agent_source:a?.nom_affiche||'',debut:getVal(form,'debut'),fin:getVal(form,'fin'),mission_securite_demandee:getVal(form,'mission_securite_demandee'),rendez_vous:getVal(form,'rendez_vous'),commentaire:getVal(form,'commentaire'),etat:'brouillon'};if(!fields.chantier_id||!fields.date||!fields.agent_id||!fields.mission_securite_demandee){toast('Chantier, agent, date et mission sont obligatoires.');return;}
const proposed={...existing,...fields,id:id||randomId()};if(mode==='publie'){const issues=conflicts(proposed);if(issues.length){toast('Publication impossible : absence ou double affectation.');const notice=document.createElement('div');notice.className='danger-panel';notice.innerHTML=`<b>Publication bloquée :</b><ul>${issues.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`;form.prepend(notice);return;}fields.etat='publie';fields.publishedAt=new Date().toISOString();fields.revision=(existing?.revision||0)+1;}
if(existing){if(existing.origine==='LAPLACE'){work.patches[id]={...(work.patches[id]||{}),...fields};}else {const idx=work.created.findIndex(x=>x.id===id);if(idx>=0)work.created[idx]={...work.created[idx],...fields};}}else{work.created.push({...fields,id:proposed.id,origine:'Tempo'});}persistWork();closeModal();render();toast(mode==='publie'?'Vacation publiée localement.':'Brouillon enregistré.');}
function modalAgent(a=null){showModal(a?'Modifier la fiche agent':'Créer un agent',`<form id="agentForm"><input type="hidden" name="id" value="${esc(a?.id||'')}"><div class="form-grid"><div class="field span-all"><label>Nom et prénom *</label><input name="nom_affiche" value="${esc(a?.nom_affiche||'')}" required></div><div class="field"><label>Téléphone</label><input name="telephone" type="tel" value="${esc(a?.telephone||'')}"></div><div class="field"><label>Adresse e-mail</label><input name="email" type="email" value="${esc(a?.email||'')}"></div><div class="field span-all"><label>Profil</label><select name="categorie"><option value="agent" ${a?.categorie!=='encadrement'?'selected':''}>Agent</option><option value="encadrement" ${a?.categorie==='encadrement'?'selected':''}>Encadrement</option></select></div><div class="field span-all"><label>Compétences déclarées (à vérifier)</label><textarea name="competences" placeholder="TES C, TES D, S11…">${esc((a?.competences_declarees||[]).join(', '))}</textarea></div></div><div class="note-panel">Les compétences saisies sont déclaratives. Tempo ne certifie pas les habilitations ni leur validité.</div><div class="form-actions"><button type="button" class="btn" data-close>Annuler</button><button class="btn btn-primary" type="submit">Enregistrer la fiche</button></div></form>`);}
function saveAgent(form){const id=getVal(form,'id'),prev=agents().find(x=>x.id===id);const vals={nom_affiche:getVal(form,'nom_affiche'),telephone:getVal(form,'telephone'),email:getVal(form,'email'),categorie:getVal(form,'categorie'),competences_declarees:getVal(form,'competences').split(',').map(x=>x.trim()).filter(Boolean)};if(!vals.nom_affiche){toast('Nom et prénom requis');return;}if(prev){if(work.agents.some(a=>a.id===id)){const i=work.agents.findIndex(a=>a.id===id);work.agents[i]={...work.agents[i],...vals};}else work.agentPatches[id]={...(work.agentPatches[id]||{}),...vals};}else{work.agents.push({...vals,id:randomId(),habilitations_confirmees:[]});}persistWork();closeModal();render();toast('Fiche agent enregistrée localement.');}
function modalAbsence(){showModal('Nouvelle indisponibilité',`<form id="absenceForm"><div class="form-grid"><div class="field span-all"><label>Agent</label><select name="agent_id" required>${agentsOpts().replace('Tous les agents','Choisir un agent')}</select></div><div class="field"><label>Date de début</label><input type="date" name="debut" required value="${iso(new Date())}"></div><div class="field"><label>Date de fin</label><input type="date" name="fin" required value="${iso(new Date())}"></div><div class="field span-all"><label>Type</label><select name="type"><option>Congé</option><option>Repos</option><option>Formation</option><option>Indisponibilité</option><option>Autre</option></select></div><div class="field span-all"><label>Commentaire</label><textarea name="note"></textarea></div></div><div class="form-actions"><button class="btn" type="button" data-close>Annuler</button><button class="btn btn-primary" type="submit">Enregistrer</button></div></form>`);}
function saveAbsence(form){const entry={id:randomId(),agent_id:getVal(form,'agent_id'),debut:getVal(form,'debut'),fin:getVal(form,'fin'),type:getVal(form,'type'),note:getVal(form,'note')};if(!entry.agent_id||entry.fin<entry.debut){toast('Agent et dates valides obligatoires.');return;}work.absences.push(entry);persistWork();closeModal();render();toast('Indisponibilité enregistrée.');}
function modalChantier(){showModal('Ajouter un chantier',`<form id="chantierForm"><div class="form-grid"><div class="field span-all"><label>Nom du chantier *</label><input name="chantier" required placeholder="Chantier …"></div><div class="field"><label>Compte / référence</label><input name="compte"></div><div class="field"><label>Contact</label><input name="contact"></div></div><div class="form-actions"><button class="btn" type="button" data-close>Annuler</button><button class="btn btn-primary" type="submit">Ajouter</button></div></form>`);}
function saveChantier(form){const nom=getVal(form,'chantier');if(!nom)return;work.chantiers.push({chantier_id:randomId(),chantier:nom,compte:getVal(form,'compte'),contact:getVal(form,'contact')});persistWork();closeModal();render();toast('Chantier créé.');}
function download(name,text,typ='application/json'){const blob=new Blob([text],{type:typ});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportAll(){download(`AINM_Tempo_Sauvegarde_${iso(new Date())}.json`,JSON.stringify({type:'ainm-tempo-backup',version:2,exportedAt:new Date().toISOString(),base,work},null,2));toast('Sauvegarde créée : garder ce fichier en lieu sûr.');}
function csvCell(x){return '"'+String(x??'').replace(/"/g,'""')+'"';}
function exportCsv(){const rows=[['Date','Début','Fin','Chantier','Agent','Mission sécurité demandée','Statut','Rendez-vous','Commentaires'],...allMissions().sort((a,b)=>a.date.localeCompare(b.date)).map(m=>[m.date,cleanTime(m.debut),cleanTime(m.fin),chantierName(m.chantier_id),missionAgentName(m),m.mission_securite_demandee,m.etat,m.rendez_vous||'',m.commentaire||''])];download('AINM_Tempo_Planning.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function exportIcs(){const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const vevents=allMissions().map(m=>{const [a,b]=dtRange(m);const stampDate=d=>`${iso(d).replaceAll('-','')}T${String(d.getHours()).padStart(2,'0')}${String(d.getMinutes()).padStart(2,'0')}00`;const icsEsc=s=>String(s??'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,c=>'\\'+c);return `BEGIN:VEVENT\r\nUID:${icsEsc(m.id)}@ainm-tempo\r\nDTSTAMP:${stamp}\r\nDTSTART:${stampDate(a)}\r\nDTEND:${stampDate(b)}\r\nSUMMARY:${icsEsc(chantierName(m.chantier_id)+' — '+missionAgentName(m))}\r\nDESCRIPTION:${icsEsc(m.mission_securite_demandee+' [Prévision Tempo ; vérifier habilitations]')}\r\nEND:VEVENT`;});download('AINM_Tempo_Planning.ics','BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//AINM Tempo//Planning//FR\r\n'+vevents.join('\r\n')+'\r\nEND:VCALENDAR','text/calendar;charset=utf-8');}
async function fileImport(file){if(!file)return;try{const raw=JSON.parse(await file.text());if(raw.type==='ainm-tempo-backup'){if(!confirm('Restaurer cette sauvegarde remplacera les modifications locales actuelles. Continuer ?'))return;const b=validateBase(raw.base);work={...DEFAULT_WORK(),...raw.work};persistWork();await importBase(b);}else await importBase(raw);}catch(e){toast('Import impossible : '+e.message);}}
function dialogActions(e){const node=e.target.closest('button,[data-open-mission],[data-agent],[data-chantier],[data-week-site],[data-sheet-close],[data-week-filter],[data-week-dayfocus]');if(!node)return;
if(node.hasAttribute('data-sheet-close')){closeWeekSheet();return;}
if(node.hasAttribute('data-week-site')){openWeekSheet(node.dataset.weekDate,node.dataset.weekSite,node);return;}
if(node.hasAttribute('data-sheet-chantier')){const id=node.dataset.sheetChantier;closeWeekSheet();selectedChantier=id;view='chantiers';render();return;}
if(node.hasAttribute('data-sheet-add')){const id=node.dataset.sheetAdd,d=node.dataset.weekDate;closeWeekSheet();modalMission(null,{chantier:id,date:d});return;}
if(node.hasAttribute('data-week-filter')){weekVisualFilter=node.dataset.weekFilter;render();return;}
if(node.hasAttribute('data-week-dayfocus')){weekDayFocus=node.dataset.weekDayfocus;render();return;}
if(node.hasAttribute('data-close')){closeModal();return;}
if(node.id==='dismissPrivacy'){localStorage.setItem('tempo_hide_privacy','1');$('privacyBanner').hidden=true;return;}
if(node.hasAttribute('data-view')){setView(node.dataset.view);return;}
if(node.hasAttribute('data-mode')){planningMode=node.dataset.mode;render();return;}
if(node.hasAttribute('data-week')){const delta=Number(node.dataset.week);weekStart=delta?addDays(weekStart,delta):monday(new Date());weekDayFocus='';render();return;}
if(node.hasAttribute('data-page')){page=Math.max(0,page+Number(node.dataset.page));render();return;}
if(node.hasAttribute('data-day')){filters.date=node.dataset.day;setView('missions');return;}
if(node.hasAttribute('data-open-mission')){closeWeekSheet();modalDetail(node.dataset.openMission);return;}
if(node.hasAttribute('data-edit-mission')){const m=byId(node.dataset.editMission);if(m)modalMission(m);return;}
if(node.hasAttribute('data-agent')){selectedAgent=node.dataset.agent;view='agents';render();return;}
if(node.hasAttribute('data-edit-agent')){modalAgent(agents().find(a=>a.id===node.dataset.editAgent));return;}
if(node.hasAttribute('data-chantier')){selectedChantier=node.dataset.chantier;view='chantiers';render();return;}
if(node.hasAttribute('data-remove-absence')){if(confirm('Retirer cette indisponibilité du planning local ?')){work.absences=work.absences.filter(a=>a.id!==node.dataset.removeAbsence);persistWork();render();}return;}
if(node.hasAttribute('data-remove-mission')){if(!confirm('Retirer cette affectation de votre planning local ? La ligne source LAPLACE reste dans la base importée.'))return;const id=node.dataset.removeMission;if(work.created.some(m=>m.id===id))work.created=work.created.filter(m=>m.id!==id);else work.hidden[id]=true;persistWork();closeModal();render();toast('Affectation masquée dans le planning local.');return;}
const act=node.dataset.action;if(!act)return;
if(act==='create'){modalMission(null,{agent:node.dataset.targetAgent||filters.agent,chantier:node.dataset.targetChantier||filters.chantier,date:filters.date||iso(new Date())});return;}
if(act==='go-planning'){setView('planning');return;}
if(act==='back-agent'){selectedAgent=null;render();return;}
if(act==='back-chantier'){selectedChantier=null;render();return;}
if(act==='agents'){setView('agents');return;}
if(act==='absence'){modalAbsence();return;}
if(act==='new-agent'){modalAgent();return;}
if(act==='create-chantier'){modalChantier();return;}
if(act==='import'){$('hiddenFile').click();return;}
if(act==='export'){exportAll();return;}
if(act==='export-csv'){exportCsv();return;}
if(act==='export-ics'){exportIcs();return;}
if(act==='clear-work'){if(confirm('Effacer les vacations créées, corrections, fiches modifiées et absences sur cet appareil ? La base LAPLACE importée sera conservée.')){work=DEFAULT_WORK();persistWork();render();toast('Travail local réinitialisé.');}return;}
}
function handleSubmit(e){const form=e.target;const formId=form.getAttribute('id');if(!['missionForm','agentForm','absenceForm','chantierForm'].includes(formId))return;e.preventDefault();if(formId==='missionForm'){const submitter=e.submitter;saveMission(form,submitter?.value||'brouillon');}if(formId==='agentForm')saveAgent(form);if(formId==='absenceForm')saveAbsence(form);if(formId==='chantierForm')saveChantier(form);}
function handleFilters(e){const n=e.target;if(n.id==='filterChantier'){filters.chantier=n.value;page=0;render();}if(n.id==='filterAgent'){filters.agent=n.value;page=0;render();}if(n.id==='filterDate'){filters.date=n.value;page=0;render();}if(n.id==='filterSearch'){filters.search=n.value;page=0;const p=n.selectionStart;render();const tgt=$('filterSearch');if(tgt){tgt.focus();tgt.setSelectionRange(p,p);}}}
async function init(){document.addEventListener('click',dialogActions);document.addEventListener('submit',handleSubmit);document.addEventListener('change',handleFilters);document.addEventListener('input',e=>{if(e.target.id==='filterSearch')handleFilters(e)});$('topCreate').addEventListener('click',()=>modalMission());$('topImport').addEventListener('click',()=>$('hiddenFile').click());$('menuToggle').addEventListener('click',()=>$('sidebar').classList.toggle('open'));$('closeModal').addEventListener('click',closeModal);$('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal();});$('weekSheet').addEventListener('click',e=>{if(e.target.classList.contains('tempo-sheet-backdrop'))closeWeekSheet();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('weekSheet').hidden)closeWeekSheet();else closeModal();}if(e.key==='Tab'&&!$('weekSheet').hidden){const links=[...$('weekSheet').querySelectorAll('button:not([disabled]),a[href],input:not([disabled])')].filter(x=>x.getClientRects().length);if(links.length){const first=links[0],last=links[links.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}if((e.key==='Enter'||e.key===' ')&&e.target.hasAttribute('data-open-mission')){e.preventDefault();modalDetail(e.target.dataset.openMission)}});$('hiddenFile').addEventListener('change',async e=>{await fileImport(e.target.files?.[0]);e.target.value='';});if(localStorage.getItem('tempo_hide_privacy'))$('privacyBanner').hidden=true;
work={...DEFAULT_WORK(),...(readJson(STORAGE_WORK)||{})};let loaded=null;try{loaded=await idbLoad();}catch{}if(!loaded)loaded=readJson(STORAGE_BASE);if(loaded){try{base=validateBase(loaded);await idbSave(base).catch(()=>{});}catch(e){console.warn('Base non chargée',e);toast('Importer la base JSON AINM depuis Données & sauvegardes.');}}render();
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
}
init();
})();
